#include "tf_framework.h"

// Per-command Arduino-library test for the device clock commands:
//   cmd 8  Reset time      (resetTime)
//   cmd 9  Get current time (getCurrentTime / getCurrentTimeRaw)
//   cmd 10 Time sync        (timeSync)
//
// Mirrors the Python tests test_reset_time.py, test_get_current_time.py and
// test_time_sync.py, adapted to the Arduino API. There is ONE motor on the bus
// and it is addressed by unique ID (extended addressing) via the wrapper, so all
// methods are called WITHOUT a uniqueId argument.
//
// Clock facts used below (from AutoGeneratedUnitConversions.h + firmware):
//   internal time unit = timesteps, one timestep = 32 us, 31250 timesteps/second.
//   getCurrentTime() in SECONDS = raw_timesteps / 31250.

static const float   NEAR_ZERO_S      = 0.5f;   // post-reset read must be under this
static const int     SLEEP_MS         = 1000;   // wall-clock sleep between reads
static const float   ELAPSED_TOL_S    = 0.25f;  // |motor elapsed - wall elapsed| bound
static const int     N_MONOTONIC      = 20;      // back-to-back monotonic samples
static const float   TIMESTEPS_PER_S  = 31250.0f;

// Time-sync single-device parameters (mirrors test_time_sync.py phases, shorter).
static const int     SYNC_DRIFT_MS    = 1000;   // idle after reset so the clock drifts
static const int     SYNC_LOCKIN_MS   = 2000;   // PI controller settling (not asserted)
static const int     SYNC_MEASURE_MS  = 2000;   // measured window
static const int     SYNC_PERIOD_MS   = 100;    // ~10 Hz, the protocol's recommended rate
// PI trims the oscillator gradually; per-call error is clamped to +/-32768 us. A single
// device can't prove multi-device correction, so we only require the response to stay
// bounded and sane (no runaway) plus no fatal error and a responsive device afterward.
static const int     SYNC_SANE_BOUND_US = 60000; // any returned |timeError| must be under this

void tm_time(void) {
    char buf[160];

    Servomotor* motor = tfGetMotor();

    // ---- Clean, known state ----
    motor->systemReset();
    delay(1500);  // motor reboots and does not respond during this window

    // =====================================================================
    // cmd 8 Reset time  +  cmd 9 Get current time
    // =====================================================================
    motor->setTimeUnit(TimeUnit::SECONDS);

    // --- Reset time: clock must read near zero immediately afterward ---
    printf("\n=== cmd 8 Reset time / cmd 9 Get current time ===\n");
    motor->resetTime();
    checkMotorError(*motor, "resetTime");
    float t_after_reset = motor->getCurrentTime();
    checkMotorError(*motor, "getCurrentTime (after reset)");
    snprintf(buf, sizeof(buf), "get_current_time after reset_time: %.6f s\n", t_after_reset);
    Serial.print(buf);
    TEST_RESULT("Current time non-negative after reset", t_after_reset >= 0.0f);
    TEST_RESULT("Current time near zero after reset", t_after_reset < NEAR_ZERO_S);

    // --- Monotonic: N back-to-back reads must be non-decreasing ---
    printf("\nReading %d samples back-to-back; sequence must be non-decreasing...\n", N_MONOTONIC);
    bool monotonic = true;
    float prev = t_after_reset;
    float last = prev;
    for (int i = 0; i < N_MONOTONIC; i++) {
        float t = motor->getCurrentTime();
        checkMotorError(*motor, "getCurrentTime (monotonic sample)");
        if (t < prev) {
            monotonic = false;
            snprintf(buf, sizeof(buf), "  NON-MONOTONIC: sample %d went backwards (%.6f -> %.6f)\n", i, prev, t);
            Serial.print(buf);
        }
        prev = t;
        last = t;
    }
    snprintf(buf, sizeof(buf), "  %d samples read, last = %.6f s\n", N_MONOTONIC, last);
    Serial.print(buf);
    TEST_RESULT("Current time is monotonic (non-decreasing)", monotonic);

    // --- Tracks wall-clock: measured elapsed matches a real sleep ---
    printf("\nSleeping %d ms; motor clock must advance ~the same amount...\n", SLEEP_MS);
    float t_before = motor->getCurrentTime();
    checkMotorError(*motor, "getCurrentTime (before sleep)");
    unsigned long wall_start = millis();
    delay(SLEEP_MS);
    float t_after = motor->getCurrentTime();
    checkMotorError(*motor, "getCurrentTime (after sleep)");
    float wall_elapsed_s = (millis() - wall_start) / 1000.0f;
    float motor_elapsed_s = t_after - t_before;
    snprintf(buf, sizeof(buf), "  motor elapsed %.4f s, wall elapsed %.4f s\n", motor_elapsed_s, wall_elapsed_s);
    Serial.print(buf);
    TEST_RESULT("Motor clock advanced over sleep", motor_elapsed_s > 0.0f);
    TEST_RESULT("Motor elapsed matches wall-clock",
                fabsf(motor_elapsed_s - wall_elapsed_s) <= ELAPSED_TOL_S);

    // --- Cross-unit physical correctness: ms~=s*1000, us~=s*1e6, timesteps~=s*31250 ---
    // The reads happen at slightly different moments, so normalize each to seconds
    // and require the sequence to be non-decreasing with each gap under 0.5 s.
    printf("\nCross-unit check: ms ~= s*1000, us ~= s*1e6, timesteps ~= s*31250...\n");
    motor->setTimeUnit(TimeUnit::SECONDS);
    float v_s = motor->getCurrentTime();
    motor->setTimeUnit(TimeUnit::MILLISECONDS);
    float v_ms = motor->getCurrentTime();
    motor->setTimeUnit(TimeUnit::MICROSECONDS);
    float v_us = motor->getCurrentTime();
    motor->setTimeUnit(TimeUnit::TIMESTEPS);
    float v_ts = motor->getCurrentTime();
    motor->setTimeUnit(TimeUnit::SECONDS);  // restore default
    checkMotorError(*motor, "getCurrentTime (cross-unit)");

    float norm_s  = v_s;
    float norm_ms = v_ms / 1000.0f;
    float norm_us = v_us / 1000000.0f;
    float norm_ts = v_ts / TIMESTEPS_PER_S;
    snprintf(buf, sizeof(buf), "  s=%.6f  ms=%.1f(->%.6f)  us=%.1f(->%.6f)  ts=%.1f(->%.6f)\n",
             v_s, v_ms, norm_ms, v_us, norm_us, v_ts, norm_ts);
    Serial.print(buf);
    float norms[4] = { norm_s, norm_ms, norm_us, norm_ts };
    bool cross_unit_ok = true;
    for (int i = 1; i < 4; i++) {
        float gap = norms[i] - norms[i - 1];
        if (gap < -0.001f || gap > 0.5f) cross_unit_ok = false;  // reads are ordered in time; gaps tiny
    }
    TEST_RESULT("Cross-unit conversions physically consistent", cross_unit_ok);

    // --- Reset is repeatable: after the clock has run, a second reset drops it near zero ---
    printf("\nSecond reset_time after the clock ran; must drop back near zero...\n");
    float t_pre_reset2 = motor->getCurrentTime();
    motor->resetTime();
    checkMotorError(*motor, "resetTime (second)");
    float t_after_reset2 = motor->getCurrentTime();
    checkMotorError(*motor, "getCurrentTime (after second reset)");
    snprintf(buf, sizeof(buf), "  before=%.6f s  after second reset=%.6f s\n", t_pre_reset2, t_after_reset2);
    Serial.print(buf);
    TEST_RESULT("Second reset drops clock near zero", t_after_reset2 < NEAR_ZERO_S);
    TEST_RESULT("Second reset actually reduced the clock", t_after_reset2 < t_pre_reset2);

    // =====================================================================
    // cmd 10 Time sync (single-device)
    // =====================================================================
    // Establish a shared epoch, let the clock drift, then discipline it at ~10 Hz.
    // With one motor we cannot verify multi-device correction, so we assert:
    //   (a) every timeSync round-trip has no communication error,
    //   (b) every returned timeError stays bounded/sane (no PI runaway),
    //   (c) no fatal error is raised, and the device stays responsive.
    printf("\n=== cmd 10 Time sync (single-device) ===\n");
    motor->setTimeUnit(TimeUnit::SECONDS);
    motor->resetTime();
    checkMotorError(*motor, "resetTime (pre-sync)");
    unsigned long sync_epoch = millis();

    printf("Phase 1 - drift: idle %d ms (no syncs)...\n", SYNC_DRIFT_MS);
    delay(SYNC_DRIFT_MS);

    bool sync_comm_ok = true;
    bool sync_bounded = true;
    int  n_sync = 0;
    int32_t last_err_us = 0;
    int32_t measure_abs_max = 0;
    int total_sync_ms = SYNC_LOCKIN_MS + SYNC_MEASURE_MS;
    printf("Phase 2/3 - sync at ~%d ms period for %d ms (first %d ms = lock-in, not asserted)...\n",
           SYNC_PERIOD_MS, total_sync_ms, SYNC_LOCKIN_MS);
    unsigned long sync_start = millis();
    while ((int)(millis() - sync_start) < total_sync_ms) {
        // master clock reading, in seconds since our shared epoch
        float master_s = (millis() - sync_epoch) / 1000.0f;
        timeSyncResponse resp = motor->timeSync(master_s);
        if (motor->getError() != 0) {
            sync_comm_ok = false;
            snprintf(buf, sizeof(buf), "  sync %d: communication error %d\n", n_sync, motor->getError());
            Serial.print(buf);
        }
        last_err_us = resp.timeError;
        bool in_measure = (int)(millis() - sync_start) >= SYNC_LOCKIN_MS;
        if (in_measure) {
            int32_t a = (resp.timeError < 0) ? -resp.timeError : resp.timeError;
            if (a > measure_abs_max) measure_abs_max = a;
            if (a >= SYNC_SANE_BOUND_US) sync_bounded = false;
        }
        n_sync++;
        delay(SYNC_PERIOD_MS);
    }
    snprintf(buf, sizeof(buf), "  sent %d syncs; last timeError=%d us; measurement-window max |err|=%d us\n",
             n_sync, last_err_us, measure_abs_max);
    Serial.print(buf);

    TEST_RESULT("Time sync sent at least a few syncs", n_sync >= 10);
    TEST_RESULT("Time sync: no communication errors", sync_comm_ok);
    TEST_RESULT("Time sync: timeError stays bounded (no PI runaway)", sync_bounded);

    // Device must have no fatal error and remain responsive after the sync burst.
    getStatusResponse st = motor->getStatus();
    checkMotorError(*motor, "getStatus (post-sync)");
    snprintf(buf, sizeof(buf), "  post-sync status flags=0x%04X fatalError=%d\n", st.statusFlags, st.fatalErrorCode);
    Serial.print(buf);
    TEST_RESULT("Time sync: no fatal error afterward", st.fatalErrorCode == 0);

    float t_resp = motor->getCurrentTime();
    checkMotorError(*motor, "getCurrentTime (post-sync responsive)");
    snprintf(buf, sizeof(buf), "  device responsive: current time = %.6f s\n", t_resp);
    Serial.print(buf);
    TEST_RESULT("Time sync: device responsive afterward", t_resp >= 0.0f);

    // ---- Leave the device clean ----
    motor->systemReset();
    delay(1500);
}
